import {
  forwardRef,
  useEffect,
  useInsertionEffect,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";

export interface BlurNumberStyle extends CSSProperties {
  /** Distance each changed character travels. Defaults to `0.55em`. */
  "--bui-blur-number-distance"?: string;
}

export interface BlurNumberProps extends Omit<
  HTMLAttributes<HTMLSpanElement>,
  "children" | "prefix" | "style"
> {
  /** Numeric value to format and animate. */
  value: number;
  /** Options forwarded to `Intl.NumberFormat`. */
  format?: Intl.NumberFormatOptions;
  /** Fixed formatting locale. Keep it stable between server and client. */
  locale?: string;
  /** Content rendered before the formatted value. */
  prefix?: ReactNode;
  /** Content rendered after the formatted value. */
  suffix?: ReactNode;
  /** Slide and blur duration in milliseconds. */
  duration?: number;
  /** Peak blur applied to changing characters in pixels. */
  blur?: number;
  /** Native styles plus the typed travel-distance variable. */
  style?: BlurNumberStyle;
}

const STYLE_ID = "boring-ui-blur-number-styles";

const STYLE_TEXT = `
.bui-blur-number {
  --bui-blur-number-spring: linear(
    0, 0.028 2.5%, 0.0995 5%, 0.198 7.5%, 0.3106 10%, 0.4272 12.5%, 0.5405 15%,
    0.6454 17.5%, 0.7387 20%, 0.819 22.5%, 0.8856 25%, 0.9391 27.5%, 0.9803 30%,
    1.0107 32.5%, 1.0317 35%, 1.045 37.5%, 1.052 40%, 1.0543 42.5%, 1.053 45%,
    1.0493 47.5%, 1.044 50%, 1.0379 52.5%, 1.0316 55%, 1.0254 57.5%, 1.0197 60%,
    1.0146 62.5%, 1.0102 65%, 1.0065 67.5%, 1.0035 70%, 1.0012 72.5%, 0.9995 75%,
    0.9984 77.5%, 0.9976 80%, 0.9972 82.5%, 0.9971 85%, 0.9971 87.5%, 0.9973 90%,
    0.9976 92.5%, 0.9979 95%, 0.9983 97.5%, 1
  );
  --bui-blur-number-distance: 0.55em;
  display: inline-flex;
  align-items: baseline;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.bui-blur-number__slot {
  position: relative;
  display: inline-block;
}

.bui-blur-number__layer {
  display: inline-block;
}

.bui-blur-number__incoming,
.bui-blur-number__outgoing {
  will-change: transform, opacity, filter;
}

.bui-blur-number__incoming {
  animation:
    bui-blur-number-slide-in var(--bui-blur-number-duration, 450ms)
      var(--bui-blur-number-spring) both,
    bui-blur-number-resolve var(--bui-blur-number-duration, 450ms)
      cubic-bezier(0.22, 1, 0.36, 1) both;
}

.bui-blur-number__outgoing {
  position: absolute;
  inset: 0;
  animation:
    bui-blur-number-slide-out var(--bui-blur-number-duration, 450ms)
      cubic-bezier(0.4, 0, 1, 1) both,
    bui-blur-number-dissolve var(--bui-blur-number-duration, 450ms)
      cubic-bezier(0.4, 0, 1, 1) both;
}

@keyframes bui-blur-number-slide-in {
  from {
    transform: translateY(
      calc(var(--bui-blur-number-direction, 1) * var(--bui-blur-number-distance))
    );
  }
  to {
    transform: translateY(0);
  }
}

@keyframes bui-blur-number-slide-out {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(
      calc(
        var(--bui-blur-number-direction, 1) * var(--bui-blur-number-distance) * -1
      )
    );
  }
}

@keyframes bui-blur-number-resolve {
  from {
    opacity: 0;
    filter: blur(var(--bui-blur-number-blur, 21px));
  }
  to {
    opacity: 1;
    filter: blur(0);
  }
}

@keyframes bui-blur-number-dissolve {
  from {
    opacity: 1;
    filter: blur(0);
  }
  to {
    opacity: 0;
    filter: blur(var(--bui-blur-number-blur, 21px));
  }
}

@media (prefers-reduced-motion: reduce) {
  .bui-blur-number__incoming {
    animation: none;
  }

  .bui-blur-number__outgoing {
    display: none;
    animation: none;
  }
}
`;

const EMPTY_CHARACTER = "\u200b";

function joinClassNames(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(" ");
}

function useBlurNumberStyles() {
  useInsertionEffect(() => {
    if (typeof document === "undefined" || document.getElementById(STYLE_ID)) return;

    const element = document.createElement("style");
    element.id = STYLE_ID;
    element.textContent = STYLE_TEXT;
    document.head.appendChild(element);
  }, []);
}

function formatValue(value: number, locale: string, format?: Intl.NumberFormatOptions) {
  try {
    return new Intl.NumberFormat(locale, format).format(value);
  } catch {
    return String(value);
  }
}

interface CharacterSlotProps {
  character: string;
  duration: number;
}

interface CharacterSlotState {
  current: string;
  outgoing: string | null;
  generation: number;
}

function CharacterSlot({ character, duration }: CharacterSlotProps) {
  const previousCharacter = useRef(character);
  const generation = useRef(0);
  const [state, setState] = useState<CharacterSlotState>(() => ({
    current: character,
    outgoing: null,
    generation: 0,
  }));

  useEffect(() => {
    if (character === previousCharacter.current) return;

    generation.current += 1;
    setState({
      current: character,
      outgoing: previousCharacter.current,
      generation: generation.current,
    });
    previousCharacter.current = character;
  }, [character]);

  useEffect(() => {
    if (state.outgoing === null) return;

    const activeGeneration = state.generation;
    const timeout = window.setTimeout(() => {
      setState((currentState) =>
        currentState.generation === activeGeneration
          ? { ...currentState, outgoing: null }
          : currentState,
      );
    }, duration + 50);

    return () => window.clearTimeout(timeout);
  }, [duration, state.generation, state.outgoing]);

  const isAnimating = state.outgoing !== null;

  function finishAnimation(animationName: string) {
    if (animationName !== "bui-blur-number-resolve") return;
    setState((currentState) =>
      currentState.generation === state.generation
        ? { ...currentState, outgoing: null }
        : currentState,
    );
  }

  return (
    <span className="bui-blur-number__slot" aria-hidden="true">
      <span
        key={`incoming-${state.generation}`}
        className={joinClassNames(
          "bui-blur-number__layer",
          isAnimating && "bui-blur-number__incoming",
        )}
        onAnimationEnd={isAnimating ? (event) => finishAnimation(event.animationName) : undefined}
      >
        {state.current === "" ? EMPTY_CHARACTER : state.current}
      </span>
      {isAnimating ? (
        <span
          key={`outgoing-${state.generation}`}
          className="bui-blur-number__layer bui-blur-number__outgoing"
        >
          {state.outgoing === "" ? EMPTY_CHARACTER : state.outgoing}
        </span>
      ) : null}
    </span>
  );
}

export const BlurNumber = forwardRef<HTMLSpanElement, BlurNumberProps>(
  (
    {
      value,
      format,
      locale = "en-US",
      prefix,
      suffix,
      duration = 450,
      blur = 21,
      className,
      style,
      role,
      "aria-label": ariaLabel,
      ...props
    },
    ref,
  ) => {
    useBlurNumberStyles();

    const safeDuration = Math.max(0, duration);
    const safeBlur = Math.max(0, blur);
    const formatted = formatValue(value, locale, format);
    const [transition, setTransition] = useState({ value, direction: 1 });

    if (transition.value !== value) {
      setTransition({
        value,
        direction: value < transition.value ? -1 : 1,
      });
    }

    const characters = formatted.split("");
    const characterCount = characters.length;
    const accessibleLabel = [
      typeof prefix === "string" ? prefix : "",
      formatted,
      typeof suffix === "string" ? suffix : "",
    ].join("");
    const blurNumberStyle = {
      ...style,
      "--bui-blur-number-duration": `${safeDuration}ms`,
      "--bui-blur-number-blur": `${safeBlur}px`,
      "--bui-blur-number-direction": transition.direction,
    } as BlurNumberStyle;

    return (
      <span
        {...props}
        ref={ref}
        className={joinClassNames("bui-blur-number", className)}
        role={role ?? "img"}
        aria-label={ariaLabel ?? accessibleLabel}
        style={blurNumberStyle}
      >
        {prefix != null ? <span aria-hidden="true">{prefix}</span> : null}
        {characters.map((character, index) => (
          <CharacterSlot
            key={characterCount - 1 - index}
            character={character}
            duration={safeDuration}
          />
        ))}
        {suffix != null ? <span aria-hidden="true">{suffix}</span> : null}
      </span>
    );
  },
);

BlurNumber.displayName = "BlurNumber";
